import numpy as np
from cad_env import CADModel, DesignProblem, FEASolver, inspect_design
import itertools

problem = DesignProblem.load_json("/app/problem.json")

def eval_design(cuts):
    model = CADModel(problem)
    for c in cuts:
        if c[0] == 'poly':
            model.cut_polygon(c[1], fillet_radius=c[2])

    report = inspect_design(problem, model)
    return report

best_cuts = None
best_score = float('inf')

for top_x in [8, 12, 16]:
    for inner_left in [4, 6, 8]:
        for inner_top_y in [24, 26]:
            for inner_bottom_y in [3, 4, 5]:
                for inner_right_x in [50, 52, 54]:
                    cuts = [
                        ('poly', [(top_x, 30), (60, 30), (60, 8)], 1.5),
                        ('poly', [(inner_left, inner_top_y), (inner_left, inner_bottom_y), (inner_right_x, inner_bottom_y)], 2.5)
                    ]
                    rep = eval_design(cuts)
                    if rep['structurally_connected'] and rep['volume_fraction'] <= 0.450:
                        if not rep.get('feature_violations'):
                            if rep['max_von_mises_stress'] <= 1.4:
                                if rep['total_compliance'] < best_score:
                                    best_score = rep['total_compliance']
                                    best_cuts = cuts
                                    print(f"New best: Vol={rep['volume_fraction']:.4f}, Comp={rep['total_compliance']:.4f}, Cuts={cuts}")

if best_cuts:
    model = CADModel(problem)
    for c in best_cuts:
        model.cut_polygon(c[1], fillet_radius=c[2])
    model.save_json("/app/design.json")
    print("Saved best design.")
